create table public.alliance_map_config (
 id integer primary key check (id=1),
 slots jsonb not null check (jsonb_typeof(slots)='array'),
 revision integer not null default 1,
 updated_at timestamptz not null default now()
);
alter table public.alliance_map_config enable row level security;
grant select on public.alliance_map_config to anon,authenticated;
grant update(slots,revision,updated_at) on public.alliance_map_config to authenticated;
create policy map_public_read on public.alliance_map_config for select to anon,authenticated using(true);
create policy map_admin_update on public.alliance_map_config for update to authenticated using(public.is_hola_r4_r5_admin()) with check(public.is_hola_r4_r5_admin());
create function public.validate_alliance_map_update() returns trigger language plpgsql set search_path='' as $$
begin
 if jsonb_array_length(new.slots)<>jsonb_array_length(old.slots) or exists(
 select 1 from jsonb_array_elements(new.slots) n full join jsonb_array_elements(old.slots) o on n->>'id'=o->>'id'
 where n is null or o is null or n->>'x' is distinct from o->>'x' or n->>'y' is distinct from o->>'y'
 ) or (select count(distinct s->>'id') from jsonb_array_elements(new.slots) s)<>jsonb_array_length(new.slots) then
 raise exception 'Las posiciones del mapa deben conservarse'; end if;
 if exists(select 1 from jsonb_array_elements(new.slots) s where jsonb_typeof(s->'name') not in ('string','null') or not(s ? 'name') or length(s->>'name')>100) or exists(
 select 1 from jsonb_array_elements(new.slots) s where nullif(trim(s->>'name'),'') is not null group by lower(trim(s->>'name')) having count(*)>1
 ) then raise exception 'Nombre inválido o jugador duplicado'; end if;
 new.revision=old.revision+1;new.updated_at=now();return new;
end; $$;
create trigger validate_map before update on public.alliance_map_config for each row execute function public.validate_alliance_map_update();

